// AWI SEO: nama entitas schema, archive tipis, title arsip, alt foto profil
add_filter( 'wpseo_schema_website', function ( $data ) {
	$data['name'] = 'BYD Makassar';
	$data['alternateName'] = 'BYD Haka Karebosi Makassar';
	return $data;
} );
add_filter( 'wpseo_schema_organization', function ( $data ) {
	$data['name'] = 'BYD Haka Karebosi Makassar';
	if ( isset( $data['logo'] ) && is_array( $data['logo'] ) ) {
		$data['logo']['caption'] = 'BYD Haka Karebosi Makassar';
	}
	return $data;
} );
add_filter( 'wpseo_robots', function ( $robots ) {
	if ( is_post_type_archive( 'event' ) && ! have_posts() ) {
		return 'noindex, follow';
	}
	return $robots;
} );
add_filter( 'wpseo_title', function ( $title ) {
	if ( is_post_type_archive( 'model' ) ) {
		return 'Semua Model Mobil BYD & Denza di Makassar 2026';
	}
	if ( is_post_type_archive( 'testimoni' ) ) {
		return 'Testimoni Pembeli BYD Makassar – Serah Terima Unit';
	}
	return $title;
} );
add_filter( 'pre_get_document_title', function ( $title ) {
	if ( is_post_type_archive( 'model' ) ) {
		return 'Semua Model Mobil BYD & Denza di Makassar 2026';
	}
	if ( is_post_type_archive( 'testimoni' ) ) {
		return 'Testimoni Pembeli BYD Makassar – Serah Terima Unit';
	}
	return $title;
}, 99 );
add_filter( 'wpseo_opengraph_title', function ( $title ) {
	if ( is_post_type_archive( 'model' ) ) {
		return 'Semua Model Mobil BYD & Denza di Makassar 2026';
	}
	return $title;
} );
add_filter( 'wpseo_metadesc', function ( $desc ) {
	if ( is_post_type_archive( 'model' ) ) {
		return 'Lihat 9 model BYD & Denza di Makassar: Atto 1, Atto 3, Dolphin, M6, M6 DM, Seal, Sealion 7, Denza D9, Z9 GT. Harga OTR dan test drive di BYD Haka Karebosi.';
	}
	return $desc;
} );
add_action( 'template_redirect', function () {
	if ( is_admin() || wp_doing_ajax() || is_feed() ) {
		return;
	}
	ob_start( function ( $html ) {
		if ( ! is_string( $html ) || '' === $html ) {
			return $html;
		}
		$html = str_replace( 'alt="A W I"', 'alt="AWI Sales Consultant BYD Haka Karebosi Makassar"', $html );
		if ( is_post_type_archive( 'model' ) ) {
			$html = preg_replace( '#(<h1\b[^>]*>(?:\s*<span\b[^>]*>)?)\s*Model Kendaraan\s*(</span>|</h1>)#i', '$1Model Mobil BYD di Makassar$2', $html, 1 );
		}
		if ( is_post_type_archive( 'testimoni' ) ) {
			$html = preg_replace( '#(<h1\b[^>]*>(?:\s*<span\b[^>]*>)?)\s*Apa Kata Mereka\s*(</span>|</h1>)#i', '$1Testimoni Pembeli BYD di Makassar$2', $html, 1 );
		}
		return $html;
	} );
}, 99 );
